@inherits UmbracoViewPage<BlockGridItem<BlogPostListBlock>>
@{
    var posts = Umbraco.AssignedContentItem
        .Children<BlogPostPage>()
        .OrderByDescending(post => post.CreateDate)
        .Select(post =>
        {
            var hero = post.Blocks?
                .Select(block => block.Content)
                .OfType<HeroBlock>()
                .FirstOrDefault();

            return new BlogPostCardModel
            {
                Title = post.Name,
                Summary = hero?.Introduction ?? string.Empty,
                Url = post.Url(),
                ImageUrl = hero?.Image?.GetCropUrl(width: 1200, height: 750),
                ImageAltText = hero?.ImageAltText ?? string.Empty,
                PublishedDate = post.CreateDate
            };
        })
        .ToArray();

    var model = new BlogPostListModel
    {
        Heading = Model.Content.Heading ?? string.Empty,
        Introduction = Model.Content.Introduction ?? string.Empty,
        Posts = posts
    };
}
@await Component.InvokeAsync("BlogPostList", new { model })

